// TH18 v1.00a st03.ecl.txt:1201-1211 MainSub05 -> GirlD01 734-812, GirlD01_at 759-812.
// Training fixes the complete 4-instance F wave (boundary/split review 2026-11-06):
// source creates at local 0/300/600/860, then MainLatter waits 540 before MainSub06.
// Source has no timeout; 1580 local covers the 4th GirlD01 through its 3rd volley and
// off-screen drift. Card limit adds the 120-frame opening buffer.
const TIME_LIMIT: int = 1700;
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;

// GirlD01_at: separate async on the same enemy; shares nothing else with the main task.
async sub shooter() {
    wait(60); // 760
    var rank: int = global(GVAR_RANK);
    var n: int = 20;       // !E
    var speed: fx = 1.2fx; // !E / !N
    if rank == 1 { n = 50; }
    if rank == 2 { n = 70; speed = 1.4fx; }
    if rank == 3 { n = 80; speed = 1.6fx; }
    // 762-787: mode10 with count=N layers=1 -> plain ring base alpha, speed s0 only.
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 4);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, speed, 0fx);
    // 787 EX type2 a=1 ANIM: keep its 4*velocity birth retreat; birth slow/no-hitbox omitted.
    sh_dist(0, -4fx * speed);
    for volley in 0..3 { // 789-809: $B=3, 120 between volleys
        // 791-806: five etOffsetRad points on an r=64 pentagon; each has its own %RANDRAD.
        sh_offset_rad(0, -90deg, 64fx);
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, -18deg, 64fx);
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 54deg, 64fx);
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 126deg, 64fx);
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        sh_offset_rad(0, 198deg, 64fx);
        sh_angle(0, rand(65536) as angle, 0deg);
        sh_fire(0);
        wait(120);
    }
}

async sub girl() {
    set_invuln(65535); // training shell
    set_hurtbox(16fx); // 750: source 32
    set_hitbox(12fx);  // 751: source 24
    move_vel(0, 90deg, 3fx, EASE_LINEAR);      // 745 moveVel(pi/2, 3)
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);    // 746 mode1 decel to 0
    spawn shooter();                            // 747
    wait(400);                                  // 748
    move_speed(120, 2fx, EASE_QUAD_IN);        // 749 mode1 accel to 2
    wait(60);                                   // 750
    loop { wait(1000); }                        // 751-756
}

async sub wave() {
    wait(OPENING_BUFFER);
    // 1203-1209: enmCreateF, parent FINAL is the stage origin; F gate fixed complete.
    _ = spawn_enemy(0fx, -48fx, 2800, 0, 0, 0, girl);
    wait(300);
    _ = spawn_enemy(64fx, -48fx, 2800, 0, 0, 0, girl);
    wait(300);
    _ = spawn_enemy(-64fx, -48fx, 2800, 0, 0, 0, girl);
    wait(260);
    _ = spawn_enemy(0fx, -48fx, 3400, 0, 0, 0, girl);
    wait(540); // 1022 MainLatter wait before MainSub06
    loop { wait(600); }
}

async sub encounter() {
    // Training-only phase owner at (0,0), no source body collision.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
